    'manual_couriers_s2' => 'After approval you get a notice saying to send by hand. Send the parcel.',
    'manual_couriers_s3' => 'Open the order. In the courier panel choose the “New step” and type the “Consignment number”, then press “Save update”.',
    'manual_couriers_s4' => 'Update the step each time you hear from the courier. A parcel can only move forward.',
    'manual_couriers_s5' => 'When the goods have really arrived, press “Confirm delivery” as usual.',
    'manual_couriers_o1' => 'The dealer sees the step and the consignment number on the order page.',
    'manual_couriers_t1' => 'Sundarban and Janani have their own public tracking page, which the dealer can open from the order.',
    'manual_couriers_w1' => 'The system cannot hear from these couriers. If nobody updates the step, the dealer keeps seeing the old one.',

    'global_search_badge' => 'Search',
    'global_search_title' => 'Searching from the top bar',
    'global_search_summary' => 'Find an order, a partner or a product from any office page.',
    'global_search_purpose' => 'The Search button is in the top bar. You can also press Ctrl+K on the keyboard.',
